import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 size 기본 20, 최대 200
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

@Controller('api/v1')
export class FnSir00301Controller {
  @Get('/help-contents')
  async listHelpContents(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    return transaction(async (db) => {
      const conditions: string[] = ["use_yn = '사용'"];
      const params: Record<string, unknown> = {};
      const menuIdRaw = query['menuId'];
      if (menuIdRaw !== undefined && menuIdRaw !== null && menuIdRaw !== '') {
        if (!/^\d+$/.test(String(menuIdRaw))) {
          throw new ApiError(400, 'VALIDATION_FAILED', '메뉴 ID는 숫자여야 합니다.');
        }
        conditions.push('menu_id = CAST(:menuId AS bigint)');
        params['menuId'] = String(menuIdRaw);
      }
      const keywordRaw = query['keyword'];
      if (keywordRaw !== undefined && keywordRaw !== null && String(keywordRaw).trim() !== '') {
        conditions.push('(title ILIKE :keyword OR content ILIKE :keyword)');
        params['keyword'] = '%' + String(keywordRaw).trim() + '%';
      }
      let page = 0;
      if (query['page'] !== undefined && query['page'] !== '') {
        if (!/^\d+$/.test(String(query['page']))) {
          throw new ApiError(400, 'VALIDATION_FAILED', '페이지 번호가 올바르지 않습니다.');
        }
        page = Number(query['page']);
      }
      let size = DEFAULT_SIZE;
      if (query['size'] !== undefined && query['size'] !== '') {
        if (!/^\d+$/.test(String(query['size'])) || Number(query['size']) < 1) {
          throw new ApiError(400, 'VALIDATION_FAILED', '페이지 크기가 올바르지 않습니다.');
        }
        size = Math.min(Number(query['size']), MAX_SIZE);
      }
      const where = ' WHERE ' + conditions.join(' AND ');
      const countRows = await db.query(
        'SELECT COUNT(*)::bigint AS "total" FROM help_content' + where,
        params,
      );
      const total = Number(countRows[0]?.['total'] ?? 0);
      const items = await db.query(
        'SELECT help_content_id AS "helpContentId", menu_id AS "menuId", title AS "title", content AS "content", manual_version AS "manualVersion" FROM help_content' +
          where +
          ' ORDER BY help_content_id LIMIT :limit OFFSET :offset',
        { ...params, limit: size, offset: page * size },
      );
      if (total === 0) {
        throw new ApiError(404, 'HELP_CONTENT_NOT_FOUND', '해당 기능에 등록된 도움말이 없습니다.');
      }
      return { items, page, size, total };
    });
  }

  @Get('/help-contents/:helpContentId')
  async getHelpContent(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const id = req.params['helpContentId'];
    if (!/^\d+$/.test(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '도움말 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT help_content_id AS "helpContentId", menu_id AS "menuId", title AS "title", content AS "content", manual_version AS "manualVersion" FROM help_content WHERE help_content_id = CAST(:id AS bigint) AND use_yn = \'사용\'',
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'HELP_CONTENT_NOT_FOUND', '도움말을 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }
}

