import { useState } from 'react';
import {
  call,
  useData,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Field,
  TextInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

export default function FnSir00301Page({ role }: PageProps) {
  const [menuId, setMenuId] = useState<number | string>('');
  const [keyword, setKeyword] = useState('');
  const [applied, setApplied] = useState<{ menuId: number | string; keyword: string }>({ menuId: '', keyword: '' });
  const [page, setPage] = useState(0);
  const [selectedId, setSelectedId] = useState<unknown>(undefined);

  const list = useData<Page>(
    () =>
      call<Page>('GET', '/help-contents', role, undefined, {
        menuId: applied.menuId,
        keyword: applied.keyword,
        page,
        size: 20,
      }),
    [applied, page, role],
  );

  const detail = useData<Row | undefined>(
    () =>
      selectedId === undefined
        ? Promise.resolve(undefined)
        : call<Row>('GET', '/help-contents/' + String(selectedId), role),
    [selectedId, role],
  );

  function search() {
    setPage(0);
    setApplied({ menuId, keyword });
  }

  function reset() {
    setMenuId('');
    setKeyword('');
    setPage(0);
    setApplied({ menuId: '', keyword: '' });
  }

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>도움말</h2>
        <Tiles items={[['조회된 도움말', <Num value={list.data ? list.data.total : 0} />]]} />
      </section>
      <section className="box span-12">
        <h2>도움말 목록</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="대상 메뉴">
            <LookupSelect table="menu" role={role} value={menuId} onChange={setMenuId} placeholder="전체" />
          </Field>
          <Field label="도움말 검색어">
            <TextInput value={keyword} onChange={setKeyword} placeholder="검색어" />
          </Field>
        </Filters>
        {list.error ? <ErrorText text={list.error} /> : null}
        <Band total={list.data ? list.data.total : 0} />
        <DataTable
          columns={[
            { key: 'title', label: '도움말 제목' },
            {
              key: 'menuId',
              label: '대상 메뉴',
              render: (r: Row) => <RefName table="menu" role={role} value={r['menuId']} />,
            },
            { key: 'manualVersion', label: '매뉴얼 버전' },
          ]}
          rows={list.data ? list.data.items : []}
          onRowClick={(r: Row) => setSelectedId(r['helpContentId'])}
          empty="도움말 미제공: 해당 기능에 등록된 도움말이 없습니다."
        />
        <Pager
          page={page}
          size={list.data ? list.data.size : 20}
          total={list.data ? list.data.total : 0}
          onPage={setPage}
        />
      </section>
      {selectedId !== undefined ? (
        <Drawer title="도움말 내용" onClose={() => setSelectedId(undefined)}>
          {detail.error ? <ErrorText text={detail.error} /> : null}
          {detail.data ? (
            <Pairs
              items={[
                ['도움말 제목', String(detail.data['title'] ?? '')],
                ['대상 메뉴', <RefName table="menu" role={role} value={detail.data['menuId']} />],
                ['매뉴얼 버전', String(detail.data['manualVersion'] ?? '')],
                ['도움말 내용', String(detail.data['content'] ?? '')],
              ]}
            />
          ) : null}
        </Drawer>
      ) : null}
    </div>
  );
}
